class CacheOwner {
  #entries = new Map<string, Entry>();       // never shared
  #queue: Promise<unknown> = Promise.resolve();

  find(key: string): Promise<Entry> {
    return (this.#queue = this.#queue.then(() => this.#findImpl(key)));
  }
  #findImpl(key: string): Entry {            // sync: cannot re-enter the queue
    if (!this.#entries.has(key)) this.#entries.set(key, Entry.of(key));
    return this.#entries.get(key)!;
  }
}
